import{_ as l,C as r,o as i,c as n,j as t,a as d,E as o,ah as c}from"./chunks/framework.BpF7DVZ1.js";const q=JSON.parse('{"title":"消息流","description":"","frontmatter":{},"headers":[],"relativePath":"components/message-feed.md","filePath":"components/message-feed.md","lastUpdated":1788635489000}'),h={name:"components/message-feed.md"},g={id:"消息流",tabindex:"-1"};function m(b,e,p,u,f,x){const s=r("Badge"),a=r("XhDemo");return i(),n("div",null,[t("h1",g,[e[0]||(e[0]=d("消息流 ",-1)),o(s,{type:"info",text:"message-feed"}),e[1]||(e[1]=d()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#消息流","aria-label":'Permalink to "消息流 <Badge type="info" text="message-feed" />"'},"​",-1))]),e[3]||(e[3]=c('<p>一段会话的消息序列：粘底跟随、条目集合语义、键盘遍历与一个统一的播报区。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>AI 对话或聊天界面的消息列表。</li><li>内容会从底部长出来，希望一直跟到底，但用户往上翻时不要被拽回去。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>内容不分条，只是一段往下追加的输出（运行日志、命令回显）：用<a href="./log">日志</a>。 两边的粘底、回到底部与播报区是同一套，差别只在要不要条目集合语义与逐条遍历。</li><li>只是一列静态卡片：用<a href="./list">列表</a>。</li><li>消息数以万计：本组件不与<a href="./virtualizer">虚拟滚动</a>组合，键盘遍历要求条目都在活 DOM 里； 长会话请配<a href="./infinite-scroll">无限滚动</a>分批加载并自行截断历史。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>粘底跟随：内容增高时自动到底，用户上滚即解除，滚回底部阈值内自动恢复。 往上插入历史消息时会补偿滚动位置，视口不跳。</li><li>「回到底部」只看在不在底、不看粘附意图：粘着但内容还没追上时按钮不该冒出来。</li><li>整份消息列表只占<strong>一个</strong> Tab 停靠位：<code>PageDown</code> / <code>PageUp</code> 在消息之间走， <code>Ctrl+End</code> / <code>Ctrl+Home</code> 一步走到消息流之外（会话界面里通常就是输入框）。</li><li>消息内容全部由作者写：气泡、头像、时间、动作条都不是本组件的部件。</li><li>新长出来的消息与冒出来的「回到底部」各带一段淡入位移；减弱动效档由令牌层压平，不必另行关闭。</li><li>「回到底部」留空时皮肤画一枚向下的字形，往按钮里塞节点即换成自己的图形。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>消息内容全由作者写；组件管的是集合语义、粘底与那一个播报区</p>',10)),o(a,{src:"message-feed/01-basic"}),e[4]||(e[4]=t("h3",{id:"粘底跟随与播报",tabindex:"-1"},[d("粘底跟随与播报 "),t("a",{class:"header-anchor",href:"#粘底跟随与播报","aria-label":'Permalink to "粘底跟随与播报"'},"​")],-1)),e[5]||(e[5]=t("p",null,"新消息长出来时自动到底，往上翻就解除；一轮结束在播报区念一句",-1)),o(a,{src:"message-feed/02-sticky"}),e[6]||(e[6]=t("h3",{id:"按角色分侧",tabindex:"-1"},[d("按角色分侧 "),t("a",{class:"header-anchor",href:"#按角色分侧","aria-label":'Permalink to "按角色分侧"'},"​")],-1)),e[7]||(e[7]=t("p",null,"条目上带 data-role，左右分侧与气泡在使用者这一侧写，组件不预设这层外观",-1)),o(a,{src:"message-feed/03-roles"}),e[8]||(e[8]=t("h3",{id:"运行态与播报",tabindex:"-1"},[d("运行态与播报 "),t("a",{class:"header-anchor",href:"#运行态与播报","aria-label":'Permalink to "运行态与播报"'},"​")],-1)),e[9]||(e[9]=t("p",null,"status 由宿主持有，组件只把它透出成 root 上的 data-state；播报只发生在 live-region 里，一轮结束才写一句",-1)),o(a,{src:"message-feed/04-status"}),e[10]||(e[10]=t("h3",{id:"触底加载更多",tabindex:"-1"},[d("触底加载更多 "),t("a",{class:"header-anchor",href:"#触底加载更多","aria-label":'Permalink to "触底加载更多"'},"​")],-1)),e[11]||(e[11]=t("p",null,"stick-change 报到底，宿主据此去取下一页；先往上翻一段再滚回底部，取回来的消息接在后面",-1)),o(a,{src:"message-feed/05-load-more"}),e[12]||(e[12]=t("h3",{id:"向上加载更早的消息",tabindex:"-1"},[d("向上加载更早的消息 "),t("a",{class:"header-anchor",href:"#向上加载更早的消息","aria-label":'Permalink to "向上加载更早的消息"'},"​")],-1)),e[13]||(e[13]=t("p",null,"视口的滚动事件直接监听：滚到接近顶部就去取上一页，取回来的插在最前面，读到一半的位置不会被顶走",-1)),o(a,{src:"message-feed/06-load-earlier"}),e[14]||(e[14]=t("h3",{id:"跳到指定的一条",tabindex:"-1"},[d("跳到指定的一条 "),t("a",{class:"header-anchor",href:"#跳到指定的一条","aria-label":'Permalink to "跳到指定的一条"'},"​")],-1)),e[15]||(e[15]=t("p",null,"消息 id 就是锚点：Vue 侧用 root 插槽给的 scrollToItem / focusItem，自定义元素侧按同一个 id 取节点自己滚",-1)),o(a,{src:"message-feed/07-scroll-to"}),e[16]||(e[16]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-message-feed&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhMessageFeedItem</code> <code>XhMessageFeedItemLabel</code> <code>XhMessageFeedList</code> <code>XhMessageFeedLiveRegion</code> <code>XhMessageFeedRoot</code> <code>XhMessageFeedScrollToEndTrigger</code> <code>XhMessageFeedViewport</code></td></tr><tr><td>组合式函数</td><td><code>useMessageFeed</code></td></tr><tr><td>状态机</td><td><code>messageFeedMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/message-feed.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;message-feed&quot;</code>：<strong><code>root</code></strong> · <strong><code>viewport</code></strong> · <strong><code>list</code></strong> · <code>item</code> · <code>item-label</code> · <code>scroll-to-end-trigger</code> · <code>live-region</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>count</code></td><td><code>number</code></td><td></td><td>消息总数，由宿主声明，不从 DOM 数；aria-setsize 取它。</td></tr><tr><td><code>status</code></td><td><code>MessageFeedStatus</code></td><td></td><td>这一轮的运行态，只落 data-state，机器不读它。</td></tr><tr><td><code>threshold</code></td><td><code>number</code></td><td></td><td>距底多少 px 视为在底，缺省用粘底原语的默认值。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>走到首尾是否回绕，默认 false——会话是线性的。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;MessageFeedTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onStickChange</code></td><td><code>(details: MessageFeedStickChangeDetails) =&gt; void</code></td><td></td><td></td></tr><tr><td><code>onItemFocus</code></td><td><code>(details: MessageFeedItemFocusDetails) =&gt; void</code></td><td></td><td></td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>stick-change</code></td><td><code>MessageFeedStickChangeDetails</code></td><td>粘底状态变化；detail 为 <code>{ atBottom: boolean, sticking: boolean }</code></td></tr><tr><td><code>item-focus</code></td><td><code>MessageFeedItemFocusDetails</code></td><td>锚点变化；detail 为 <code>{ id: string | null }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhMessageFeedRoot</code></td><td><code>default</code></td><td><code>MessageFeedRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>props.status</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td>&#39;hidden&#39; | &#39;visible&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>STICK.CHANGE</code> · <code>SCROLL_TO_BOTTOM</code> · <code>ITEM.FOCUS</code> · <code>FEED.BLUR</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useMessageFeed</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>status</code></td><td><code>MessageFeedStatus</code></td><td></td></tr><tr><td><code>atBottom</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>sticking</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>focusedId</code></td><td><code>string | null</code></td><td>roving tabindex 的锚点。</td></tr><tr><td><code>showScrollToEndTrigger</code></td><td><code>boolean</code></td><td>是否显示回到底部按钮：只看在不在底，不看粘附意图。</td></tr><tr><td><code>scrollToBottom</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>scrollToItem</code></td><td><code>(id: string) =&gt; void</code></td><td>把某条消息滚进可视区；那条不在活 DOM 里时什么都不做。</td></tr><tr><td><code>focusItem</code></td><td><code>(id: string) =&gt; void</code></td><td>把焦点落到某条消息上；那条不在活 DOM 里时什么都不做。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getListProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: MessageFeedItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemLabelProps</code></td><td><code>(props: Pick&lt;MessageFeedItemProps, &#39;id&#39;&gt;) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getScrollToEndTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getLiveRegionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/feed/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>PageDown</code></td><td>焦点在消息流内</td><td>焦点移到下一条消息；到末条时按 loop 决定回绕还是不动</td></tr><tr><td><code>PageUp</code></td><td>焦点在消息流内</td><td>焦点移到上一条消息；到首条时按 loop 决定回绕还是不动</td></tr><tr><td><code>Control+End</code></td><td>焦点在消息流内</td><td>焦点移到消息流之后的第一个可聚焦元素，会话界面里通常是输入框</td></tr><tr><td><code>Control+Home</code></td><td>焦点在消息流内</td><td>焦点移到消息流之前的最后一个可聚焦元素</td></tr><tr><td><code>Tab</code></td><td>焦点在消息流内外之间移动</td><td>整份消息列表只占一个 Tab 停靠位：没有锚点时由根容器认领并把焦点转投给第一条，有锚点时那一条认领、根容器让位</td></tr><tr><td><code>ArrowUp</code> / <code>ArrowDown</code> / <code>Home</code> / <code>End</code></td><td>焦点落在某条消息上</td><td>组件不接管，浏览器滚动最近的可滚动祖先</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在回到底部按钮上</td><td>滚回底部并恢复粘附（原生按钮激活）</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>aria-label</code></td><td>translations?.feed</td></tr><tr><td><code>list</code></td><td><code>role</code></td><td>&#39;feed&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-label</code></td><td>undefined | itemLabel(item.index + 1, count ?? -1, item.role)</td></tr><tr><td><code>item</code></td><td><code>aria-labelledby</code></td><td>scope.partId(&#39;message-feed&#39;, <code>item-label:${item.id}</code>) | undefined</td></tr><tr><td><code>item</code></td><td><code>aria-posinset</code></td><td>item.index + 1</td></tr><tr><td><code>item</code></td><td><code>aria-setsize</code></td><td>props.count</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;article&#39;</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>aria-label</code></td><td>translations?.scrollToBottom</td></tr><tr><td><code>live-region</code></td><td><code>aria-atomic</code></td><td>&#39;true&#39;</td></tr><tr><td><code>live-region</code></td><td><code>aria-live</code></td><td>&#39;polite&#39;</td></tr></tbody></table><ul><li><code>role=feed</code> 配 <code>role=article</code>，带 <code>aria-posinset</code> / <code>aria-setsize</code>；总数由 <code>count</code> 声明， 不从 DOM 数——虚拟化或分页时 DOM 里的条数不等于会话长度。</li><li>集合语义落在内容层而不是最外层：<code>role=feed</code> 只认 <code>role=article</code> 的子节点， 而播报区与回到底部按钮都是最外层的孩子。最外层只当 Tab 停靠点与键盘宿主。</li><li>播报走独立的原子区：一份会话只该有一个活区，每条消息各开一个会互相打断。</li><li>消息流本身不发 <code>aria-busy</code>：它会压住同一棵子树内播报区的播报。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/message-feed.css</code> 按部件选择：<code>[data-scope=&quot;message-feed&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>props.status</td></tr><tr><td><code>item</code></td><td><code>data-role</code></td><td>item.role</td></tr><tr><td><code>item</code></td><td><code>data-streaming</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-state</code></td><td>&#39;hidden&#39; | &#39;visible&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-message-feed-gap</code> · <code>--xh-message-feed-icon-size</code> · <code>--xh-message-feed-item-gap</code> · <code>--xh-message-feed-item-radius</code> · <code>--xh-message-feed-label-fg</code> · <code>--xh-message-feed-label-font-size</code> · <code>--xh-message-feed-p</code> · <code>--xh-message-feed-scroll-to-end-trigger-bg</code> · <code>--xh-message-feed-scroll-to-end-trigger-bg-hover</code> · <code>--xh-message-feed-scroll-to-end-trigger-border</code> · <code>--xh-message-feed-scroll-to-end-trigger-fg</code> · <code>--xh-message-feed-scroll-to-end-trigger-inset</code> · <code>--xh-message-feed-scroll-to-end-trigger-radius</code> · <code>--xh-message-feed-scroll-to-end-trigger-shadow</code> · <code>--xh-message-feed-scroll-to-end-trigger-size</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-message-feed-button-in</code> · <code>xh-message-feed-item-in</code> 随皮肤自带，不引用别处文件里的名字；<code>background</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>正文用<a href="./markdown-stream">流式正文</a>，代码用<a href="./code-view">代码视图</a>。</li><li>每条消息的动作条用<a href="./toolbar">工具条</a>，复制那一格用<a href="./clipboard">剪贴板</a>。</li><li>加载更早的消息用<a href="./infinite-scroll">无限滚动</a>，<strong>必须把消息流的滚动容器交给它</strong>， 否则它的提前量只对窗口视口生效。</li><li>空会话用<a href="./empty-state">空状态</a>，并显式把它的 <code>live</code> 设成 <code>off</code>： 它默认会成为活区，放在消息流里会与播报区抢播报。</li><li>要左右分侧或气泡：条目上带 <code>data-role</code>（<code>user</code> / <code>assistant</code> / <code>system</code>）， 在自己的样式表里按它写 <code>align-self</code>、底色、内衬与最大行宽即可，组件不预设这层外观。</li><li>还在流式写入的条目带 <code>data-streaming</code>，这是留给使用者的钩子：正文走<a href="./markdown-stream">流式正文</a>时 那枚光标就是「还在写」的标记；正文不经它渲染时，可按这个属性自己加一个非遮蔽式的标记， 例如前导色条或一格标签态。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>条目必须是内容层的<strong>直接子节点</strong>：向上插入历史消息时的滚动补偿只在直接子节点里挑锚点， 套一层壳或用 <code>display: contents</code> 都会让补偿静默失效。</li><li>一轮流结束时把整段最终文本写进播报区，别每来一个 token 写一次。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>给每条消息各写一个 <code>tabindex=&quot;0&quot;</code>：两百条消息就是两百个 Tab 停靠位。</li><li>在消息流里再套一层滚动容器：粘底句柄认的是本组件的视口，套一层它就不动了。</li><li>按 <code>data-streaming</code> 把整条消息压暗或虚化：一轮流可能持续数分钟，被盖住的正是读者正在逐字读的内容。</li></ul>',48))])}const k=l(h,[["render",m]]);export{q as __pageData,k as default};
